interface Window{go?:{main?:{App?:{GetSystemStatus:()=>Promise<VarnqorSystemStatus>;GetSettings:()=>Promise<VarnqorSettings>;SaveSettings:(value:VarnqorSettings)=>Promise<VarnqorSettings>;RunDoctor:()=>Promise<DoctorReport>}}}}
